
CURRICULUM = [{'day': 1, 'title': 'Day 1: Genesis - Thinking Like a Python Programmer', 'description': 'Master variables as labeled storage boxes, primitive data types, string formatting, and executing instructions line-by-line.', 'badge': 'First Code Spark', 'sessions': {'m1_concept': {'title': 'Morning 1: The Magic of Python and Variables', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Why Python Powers Modern Tech', 'analogy': '💡 Think of Python like universal English for computers: clean, readable, and expressive. NASA uses it to analyze telescope telemetry, Netflix uses it for AI recommendations, and OpenAI builds AI models with it.', 'content': 'Python is an interpreted, high-level programming language. It executes your instructions line-by-line from top to bottom.'}, {'heading': 'Variables: The Labeled Storage Boxes', 'analogy': '📦 Imagine a warehouse filled with labeled boxes. Writing `user_age = 25` creates a storage box labeled user_age and places the integer 25 inside. Writing `user_age = 26` replaces the contents.', 'code_example': "# Line 1: Creates variable user_name with text (str)\nuser_name = 'Alex'\n\n# Line 2: Creates variable user_age with whole number (int)\nuser_age = 24\n\n# Line 3: Creates variable account_balance with decimal number (float)\naccount_balance = 1250.75\n\n# Line 4: Boolean flag (bool)\nis_active_student = True\n\n# Line 5-6: Display output to screen using print()\nprint('Student Name:', user_name)\nprint('Account Balance: $', account_balance)", 'code_breakdown': [{'part': "user_name = 'Alex'", 'role': 'Variable Assignment', 'explanation': 'Allocates space in RAM and creates a reference named user_name pointing to the text string Alex.'}, {'part': 'account_balance = 1250.75', 'role': 'Float Data Type', 'explanation': 'Floating-point number used for precise fractional measurements and currencies.'}, {'part': 'print(...)', 'role': 'Built-in Function', 'explanation': 'Standard Python command to output and inspect text or numbers on the terminal screen.'}], 'takeaways': ['Variables store data in memory with a descriptive label.', 'Python dynamically infers data types (str, int, float, bool).', 'print(...) is your primary window to inspect results.']}], 'quiz': [{'question': 'What happens in memory when you execute: score = 100?', 'options': ['It allocates a storage spot labeled score with integer 100', 'It permanently locks 100 into the CPU hardware', 'It prints 100 immediately to the terminal screen', 'It creates a database table called score'], 'correct': 0, 'explanation': 'Variables create a named reference pointing to the object in memory.'}, {'question': 'Which variable name follows Python PEP 8 snake_case convention?', 'options': ['user-score', 'UserScore', 'user_score', '2nd_score'], 'correct': 2, 'explanation': 'Standard Python variable naming uses lowercase letters separated by underscores (snake_case).'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - Variables and Arithmetic', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Calculate the subtotal, tax amount, and final total of a retail invoice.', 'starter_code': "# ==========================================\n# INVOICE CALCULATOR LAB\n# ==========================================\n\nunit_price = 45.50\nquantity = 3\nsales_tax_rate = 0.08  # 8% sales tax\n\n# STEP 1: Compute subtotal (unit_price * quantity)\nsubtotal = unit_price * quantity\n\n# STEP 2: Compute sales tax (subtotal * sales_tax_rate)\ntax_amount = subtotal * sales_tax_rate\n\n# STEP 3: Compute final total\nfinal_total = subtotal + tax_amount\n\n# STEP 4: Output formatted results\nprint('Subtotal: $', round(subtotal, 2))\nprint('Tax Amount: $', round(tax_amount, 2))\nprint('Final Invoice Total: $', round(final_total, 2))\n", 'code_breakdown': [{'part': 'unit_price * quantity', 'role': 'Multiplication Operator (*)', 'explanation': 'Calculates raw purchase cost before tax.'}, {'part': 'round(tax_amount, 2)', 'role': 'round() Built-in', 'explanation': 'Rounds floating numbers to exactly 2 decimal places.'}], 'goal': 'Execute the code and confirm Subtotal, Tax Amount, and Final Invoice Total print accurately.', 'hints': ['Arithmetic operators: + (add), - (subtract), * (multiply), / (divide), // (integer divide), % (modulo/remainder).', 'Try changing quantity from 3 to 10 to see instant calculation updates.'], 'test_case': {'expected_output_contains': ['Subtotal: $ 136.5', 'Final Invoice Total: $ 147.42']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall and Memory Sprint', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Python Fundamentals', 'cards': [{'id': 'd1_c1', 'question': 'What are the 4 fundamental primitive data types in Python?', 'answer': "1. int (whole numbers: 42)\n2. float (decimals: 3.14)\n3. str (text: 'hello')\n4. bool (flags: True / False)", 'code_snippet': "age = 25          # int\nrate = 0.08       # float\nname = 'PyLearn'  # str\nis_valid = True   # bool"}, {'id': 'd1_c2', 'question': 'How do you embed variables inside strings using modern f-strings?', 'answer': 'Prefix the string with f and enclose variables inside curly braces {}.', 'code_snippet': "user = 'Sarah'\nxp = 250\nprint(f'User {user} has earned {xp} XP!')"}, {'id': 'd1_c3', 'question': 'What is the difference between / and // operators in Python?', 'answer': '/ returns a floating-point decimal (7 / 2 = 3.5).\n// performs floor/integer division (7 // 2 = 3).', 'code_snippet': 'print(7 / 2)   # 3.5\nprint(7 // 2)  # 3\nprint(7 % 2)   # 1 (modulo remainder)'}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated Energy and Bill Estimator', 'duration_min': 30, 'type': 'mini_project', 'category': 'Automation & Scripting', 'instruction': 'Build a home power consumption estimator that computes electrical appliance usage and splits utility expenses among roommates.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Automated Energy & Roommate Splitter\n# ====================================================\n\nac_kwh_daily = 14.5\nrefrigerator_kwh_daily = 2.0\nworkstation_kwh_daily = 3.5\n\nbilling_days = 30\nrate_per_kwh = 0.15\nroommates = 3\n\ntotal_kwh = (ac_kwh_daily + refrigerator_kwh_daily + workstation_kwh_daily) * billing_days\ntotal_bill = total_kwh * rate_per_kwh\nshare_per_person = total_bill / roommates\n\nprint('=== ⚡ MONTHLY UTILITY CONSUMPTION REPORT ===')\nprint(f'Total Energy Used: {total_kwh:.1f} kWh')\nprint(f'Total Monthly Bill: ${total_bill:.2f}')\nprint(f'Each Person Pays: ${share_per_person:.2f}')\n", 'code_breakdown': [{'part': "f'{total_bill:.2f}'", 'role': 'String Format Specifier', 'explanation': "':.2f' ensures currency values always display exactly two decimal digits."}, {'part': 'rate_per_kwh = 0.15', 'role': 'Constant Parameter', 'explanation': 'Configurable variable allowing easy updates when electricity tariffs change.'}], 'hints': ['Try changing roommates to 4 and see the recalculation.']}}}, {'day': 2, 'title': 'Day 2: Decisions and Logic - Conditionals and Flow Control', 'description': 'Teach Python to make intelligent decisions using if, elif, else, logical operators (and, or, not), and truthy/falsy evaluations.', 'badge': 'Logic Architect', 'sessions': {'m1_concept': {'title': 'Morning 1: Conditionals and The Bouncer Metaphor', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Control Flow: The Decision Tree', 'analogy': '🚪 Think of an `if-elif-else` statement like a nightclub bouncer checking tickets: If you hold a VIP pass, enter VIP Lounge. Else if you have general admission, enter Main Hall. Else, deny entry.', 'content': 'Python uses 4-space indentation to define blocks of code that execute only when conditions evaluate to True.'}, {'heading': 'Comparison & Boolean Logic', 'analogy': '⚖️ Comparison operators evaluate truths: `==` (equality), `!=` (inequality), `>`, `<`, `>=`, `<=`. Combine statements using `and`, `or`, and `not`.', 'code_example': "cpu_load = 88.5\nis_backup_running = True\n\nif cpu_load > 85 and is_backup_running:\n    print('CRITICAL: High CPU load during backup! Throttling tasks...')\nelif cpu_load > 85:\n    print('WARNING: High CPU load detected.')\nelse:\n    print('STATUS: System operating normally.')", 'code_breakdown': [{'part': 'if cpu_load > 85 and is_backup_running:', 'role': 'Compound Condition', 'explanation': '`and` requires both conditions to be True for this block to execute.'}, {'part': 'elif cpu_load > 85:', 'role': 'Fallback Condition', 'explanation': '`elif` runs only if preceding `if` condition was False.'}]}], 'quiz': [{'question': 'What is the difference between = and == in Python?', 'options': ['= is assignment (stores a value), while == is comparison (checks equality)', '= is comparison, while == is assignment', 'They are interchangeable in Python 3', '== is only for comparing numbers'], 'correct': 0, 'explanation': '`=` assigns a value to a variable, while `==` checks whether two values are equal.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - Automated Quality Inspector', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Write an automated telemetry anomaly detection script for an AI sensor pipeline.', 'starter_code': "# ==========================================\n# TELEMETRY ANOMALY DETECTOR\n# ==========================================\n\nsensor_temp_celsius = 104.5\nsensor_pressure_psi = 38.2\nis_sensor_calibrated = True\n\ndef evaluate_sensor(temp, pressure, calibrated):\n    if not calibrated:\n        return 'CRITICAL: Sensor not calibrated!'\n    if temp > 100 and pressure > 35:\n        return 'DANGER: High Temp AND High Pressure!'\n    elif temp > 100:\n        return 'WARNING: Thermal threshold exceeded.'\n    elif pressure > 35:\n        return 'WARNING: Pressure threshold exceeded.'\n    else:\n        return 'OPTIMAL: Sensor within safe operating envelope.'\n\nresult = evaluate_sensor(sensor_temp_celsius, sensor_pressure_psi, is_sensor_calibrated)\nprint('Telemetry Diagnostic Result:', result)\n", 'code_breakdown': [{'part': 'if not calibrated:', 'role': 'Guard Clause', 'explanation': 'Immediately catches invalid sensor states before proceeding to complex numeric checks.'}, {'part': "return 'DANGER: ...'", 'role': 'Function Exit', 'explanation': 'Returns diagnostic message and exits function immediately.'}], 'goal': 'Run the diagnostic test and inspect the branch evaluation.', 'hints': ['Try setting `is_sensor_calibrated = False` to observe the guard clause behavior.'], 'test_case': {'expected_output_contains': ['Telemetry Diagnostic Result: DANGER: High Temp AND High Pressure!']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Logic and Truth Tables', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Control Flow & Logic', 'cards': [{'id': 'd2_c1', 'question': 'What are Truthy and Falsy values in Python?', 'answer': "Values that automatically evaluate to False in boolean contexts:\n0, 0.0, '', [], {}, set(), None.\nAll non-zero numbers and non-empty collections evaluate to True.", 'code_snippet': "pending_items = []\nif not pending_items:\n    print('Queue is currently empty!')"}, {'id': 'd2_c2', 'question': 'How do you write a one-line ternary conditional in Python?', 'answer': 'Syntax: `value_if_true if condition else value_if_false`', 'code_snippet': "score = 85\nstatus = 'Pass' if score >= 70 else 'Fail'\nprint(status)  # 'Pass'"}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated Security Gatekeeper', 'duration_min': 30, 'type': 'mini_project', 'category': 'Software Engineering & Security', 'instruction': 'Build an authentication gateway validating username formats, password complexity, and IP subnet whitelists.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Automated Security Gatekeeper\n# ====================================================\n\nusername = 'admin_ops'\npassword_input = 'PythonMastery2026!'\nclient_ip = '192.168.1.45'\n\n# Validation Rules\nmin_length = 8\nis_whitelisted = client_ip.startswith('192.168.') or client_ip == '127.0.0.1'\nhas_special = any(char in '!@#$%^&*()-_=+' for char in password_input)\nhas_digit = any(char.isdigit() for char in password_input)\n\nprint(f'Inspecting access request for {username} from {client_ip}...')\n\nif not is_whitelisted:\n    print('🚫 ACCESS REJECTED: Client IP is outside approved internal subnet!')\nelif len(password_input) < min_length:\n    print('🚫 ACCESS REJECTED: Password must be at least 8 characters!')\nelif not has_special:\n    print('🚫 ACCESS REJECTED: Password must contain a special symbol!')\nelif not has_digit:\n    print('🚫 ACCESS REJECTED: Password must contain at least one numeric digit!')\nelse:\n    print('✅ ACCESS GRANTED: Authentication successful. Token issued.')\n", 'code_breakdown': [{'part': "client_ip.startswith('192.168.')", 'role': 'String Method', 'explanation': 'Checks if the IP string starts with the approved local subnet prefix.'}, {'part': 'any(char.isdigit() for char in password_input)', 'role': 'Generator Comprehension with any()', 'explanation': 'Returns True if at least one character in the password is a numeric digit.'}], 'hints': ['Try entering a weak password to verify rejection messages.']}}}, {'day': 3, 'title': 'Day 3: The Assembly Line - Loops and Iteration', 'description': 'Automate batch tasks effortlessly using for loops, while loops, enumerate(), break, and continue statements.', 'badge': 'Automation Engine', 'sessions': {'m1_concept': {'title': 'Morning 1: Loops - The Relentless Factory Robot', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Why Loops are the Heart of Automation', 'analogy': '🏭 Imagine you have to inspect 1,000,000 sensor readings. Without loops, you would have to write 1,000,000 lines of code. With a loop, you write 2 lines of code and the computer executes it in milliseconds.', 'content': 'A `for` loop iterates over elements in any sequence (lists, strings, ranges). A `while` loop repeats continuously as long as a condition evaluates to True.'}, {'heading': 'Loop Controls: break and continue', 'analogy': '⚡ `break` hits the emergency stop button and exits the loop immediately. `continue` skips the rest of the current iteration and jumps to the next item.', 'code_example': "# Inspect batch tasks\nfor task_id in range(1, 6):\n    if task_id == 3:\n        print(f'Skipping task #{task_id} (Maintenance window)')\n        continue\n    print(f'Executing automated task #{task_id} complete.')", 'code_breakdown': [{'part': 'range(1, 6)', 'role': 'Range Generator', 'explanation': 'Generates numbers 1, 2, 3, 4, 5 (up to but not including 6).'}, {'part': 'continue', 'role': 'Loop Directive', 'explanation': 'Skips printing for task #3 and proceeds immediately to task #4.'}]}], 'quiz': [{'question': 'What sequence of numbers does range(2, 6) produce?', 'options': ['2, 3, 4, 5', '2, 3, 4, 5, 6', '1, 2, 3, 4, 5, 6', '6, 5, 4, 3, 2'], 'correct': 0, 'explanation': 'Python ranges are half-open intervals: start (inclusive) to stop (exclusive).'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - Automated Log Stream Analyzer', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Iterate through server log HTTP status codes, count successful requests, and calculate the overall error rate.', 'starter_code': "# ==========================================\n# SERVER LOG STREAM ANALYZER\n# ==========================================\n\nhttp_status_codes = [200, 200, 404, 200, 500, 200, 200, 403, 200, 502]\n\nsuccess_count = 0\nerror_count = 0\n\nfor status in http_status_codes:\n    if status == 200:\n        success_count += 1\n    else:\n        error_count += 1\n\ntotal_requests = len(http_status_codes)\nerror_rate_pct = (error_count / total_requests) * 100\n\nprint(f'Total Log Records Processed: {total_requests}')\nprint(f'Successful Requests (200 OK): {success_count}')\nprint(f'Failed Requests (Errors): {error_count}')\nprint(f'Calculated Error Rate: {error_rate_pct:.1f}%')\n", 'code_breakdown': [{'part': 'for status in http_status_codes:', 'role': 'Sequence Iteration', 'explanation': "Assigns each status code one-by-one to variable 'status' during each loop pass."}, {'part': 'success_count += 1', 'role': 'Accumulator', 'explanation': 'Increments the counter variable by 1 on every match.'}], 'goal': 'Verify the calculation counts 6 successful requests and 4 errors (40.0% error rate).', 'hints': ['Notice how len() returns the total count of elements in the list.'], 'test_case': {'expected_output_contains': ['Total Log Records Processed: 10', 'Calculated Error Rate: 40.0%']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Loop Patterns', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Loops & Iteration', 'cards': [{'id': 'd3_c1', 'question': 'How do you retrieve both the index (0, 1, 2...) and the item simultaneously in a loop?', 'answer': 'Use Python built-in `enumerate(iterable, start=0)` function.', 'code_snippet': "frameworks = ['PyTorch', 'TensorFlow', 'Scikit-Learn']\nfor idx, item in enumerate(frameworks, start=1):\n    print(f'{idx}. {item}')"}, {'id': 'd3_c2', 'question': 'What is the danger of a while loop without a state update?', 'answer': 'It causes an infinite loop that freezes execution and exhausts CPU resources.', 'code_snippet': 'counter = 0\nwhile counter < 5:\n    print(counter)\n    counter += 1  # Crucial update!'}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - AI Training Loss Tracker & Early Stopping', 'duration_min': 30, 'type': 'mini_project', 'category': 'Data Science & AI/ML', 'instruction': 'Simulate an AI neural network training loop calculating loss decay per epoch and triggering Early Stopping when target convergence is met.', 'starter_code': "# ====================================================\n# MINI-PROJECT: AI Training Loss & Early Stopping\n# ====================================================\nimport random\n\ntotal_epochs = 10\ntarget_loss_threshold = 0.05\ncurrent_loss = 1.0\n\nprint('🚀 Starting Deep Learning Training Session...')\nprint(f'Target Convergence Loss: {target_loss_threshold}')\nprint('-' * 45)\n\nfor epoch in range(1, total_epochs + 1):\n    decay_rate = 0.65 + (random.random() * 0.08)\n    current_loss = round(current_loss * decay_rate, 4)\n    print(f'Epoch [{epoch:02d}/{total_epochs:02d}] -> Current Loss: {current_loss:.4f}')\n    if current_loss <= target_loss_threshold:\n        print(f'🎯 Target loss achieved at Epoch {epoch}! Triggering Early Stopping.')\n        break\nelse:\n    print('⚠️ Training completed all epochs without reaching target convergence.')\n", 'code_breakdown': [{'part': 'for epoch in range(1, total_epochs + 1):', 'role': 'Epoch Loop', 'explanation': 'Drives the simulated training cycle through each epoch step.'}, {'part': 'for ... else:', 'role': 'Loop Else Clause', 'explanation': "The 'else' block executes only if the loop finishes naturally without encountering a 'break'."}], 'hints': ['Try modifying target_loss_threshold to 0.01 or 0.1 to see how early stopping dynamically reacts.']}}}, {'day': 4, 'title': 'Day 4: The Data Vault - Lists, Dicts and Data Wrangling', 'description': 'Master core collections: Lists for ordered sequences, Dictionaries for O(1) key-value lookups, Sets for unique memberships, and List Comprehensions.', 'badge': 'Data Wrangler', 'sessions': {'m1_concept': {'title': 'Morning 1: Lists vs. Dictionaries - The Database of Python', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Choosing the Right Data Structure', 'analogy': "📚 A List `['a', 'b', 'c']` is like a numbered playlist: items are ordered by index (0, 1, 2). A Dictionary `{'name': 'Alice', 'role': 'Engineer'}` is like a phonebook: you look up values instantly using a unique key name with O(1) constant speed.", 'content': 'Dictionaries (`dict`) and Lists (`list`) form the foundation of JSON APIs, machine learning datasets, and tabular databases in Python.'}], 'quiz': [{'question': 'How do you safely look up a dictionary key without risking a KeyError crash?', 'options': ['my_dict.get(key, default_value)', 'my_dict[key]', 'my_dict.search(key)', 'my_dict.find(key)'], 'correct': 0, 'explanation': '`.get(key, default)` returns the default fallback safely if the key does not exist.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - AI Dataset Aggregator', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Filter student dataset records for the AI/ML track and compute the average exam score using list comprehension.', 'starter_code': "# ==========================================\n# AI DATASET AGGREGATOR\n# ==========================================\n\nstudents_dataset = [\n    {'name': 'Emma', 'score': 92, 'track': 'AI/ML'},\n    {'name': 'Liam', 'score': 78, 'track': 'Automation'},\n    {'name': 'Sophia', 'score': 95, 'track': 'AI/ML'},\n    {'name': 'Noah', 'score': 88, 'track': 'Software Eng'},\n    {'name': 'Olivia', 'score': 84, 'track': 'AI/ML'}\n]\n\n# STEP 1: Filter students enrolled in AI/ML track\nai_students = [s for s in students_dataset if s['track'] == 'AI/ML']\n\n# STEP 2: Calculate aggregate score\ntotal_score = sum(s['score'] for s in ai_students)\navg_score = total_score / len(ai_students)\n\nprint(f'AI/ML Enrolled Count: {len(ai_students)}')\nprint(f'Average AI/ML Exam Score: {avg_score:.2f}')\n", 'code_breakdown': [{'part': "[s for s in students_dataset if s['track'] == 'AI/ML']", 'role': 'List Comprehension', 'explanation': 'Concise and performant syntax to filter and transform lists in a single readable line.'}, {'part': "sum(s['score'] for s in ai_students)", 'role': 'Generator Expression inside sum()', 'explanation': 'Computes total score efficiently without allocating an unnecessary intermediate list.'}], 'goal': 'Execute the aggregator and verify 3 AI students with an average score of 90.33.', 'hints': ['List comprehensions `[expression for item in iterable if condition]` are a Python signature pattern.'], 'test_case': {'expected_output_contains': ['AI/ML Enrolled Count: 3', 'Average AI/ML Exam Score: 90.33']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Data Structures', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Data Structures', 'cards': [{'id': 'd4_c1', 'question': 'What is the primary difference between a List and a Set?', 'answer': 'A List is ordered and allows duplicate elements.\nA Set (`set()`) is unordered, contains only UNIQUE elements, and offers instant O(1) membership checks.', 'code_snippet': "raw_tags = ['ai', 'python', 'ai', 'data']\nunique_tags = set(raw_tags)\nprint(unique_tags)  # {'ai', 'python', 'data'}"}, {'id': 'd4_c2', 'question': 'How do you merge two dictionaries in Python 3.9+?', 'answer': 'Use the dictionary union operator `|`.', 'code_snippet': "default_cfg = {'theme': 'dark', 'font': 14}\nuser_cfg = {'font': 16, 'show_line_nums': True}\nfinal_cfg = default_cfg | user_cfg\nprint(final_cfg)"}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Warehouse Stock & Reorder Alert Engine', 'duration_min': 30, 'type': 'mini_project', 'category': 'Automation & Scripting', 'instruction': 'Build an automated inventory tracking script that evaluates SKU stock counts, calculates warehouse valuation, and generates reorder lists.', 'starter_code': '# ====================================================\n# MINI-PROJECT: Warehouse Inventory & Stock Alert\n# ====================================================\n\ninventory = {\n    \'SKU-101\': {\'name\': \'NVIDIA RTX 4090 GPU\', \'stock\': 4, \'unit_price\': 1599.00, \'min_threshold\': 5},\n    \'SKU-102\': {\'name\': \'32GB DDR5 RAM Stick\', \'stock\': 28, \'unit_price\': 89.50, \'min_threshold\': 10},\n    \'SKU-103\': {\'name\': \'2TB NVMe SSD Drive\', \'stock\': 2, \'unit_price\': 149.99, \'min_threshold\': 8},\n    \'SKU-104\': {\'name\': \'1000W Modular PSU\', \'stock\': 15, \'unit_price\': 189.00, \'min_threshold\': 5}\n}\n\ntotal_valuation = 0.0\nreorder_items = []\n\nprint(\'=== 📦 WAREHOUSE INVENTORY AUDIT ===\\n\')\nfor sku, item in inventory.items():\n    item_val = item[\'stock\'] * item[\'unit_price\']\n    total_valuation += item_val\n    if item[\'stock\'] < item[\'min_threshold\']:\n        reorder_qty = (item[\'min_threshold\'] * 2) - item[\'stock\']\n        reorder_items.append((item[\'name\'], reorder_qty))\n        print(f\'🚨 [REORDER ALERT] {item["name"]}: Stock ({item["stock"]}) below threshold ({item["min_threshold"]}). Order {reorder_qty} units.\')\n    else:\n        print(f\'✅ [OK] {item["name"]}: Healthy stock level ({item["stock"]} units in stock).\')\n\nprint(\'\\n\' + \'=\' * 45)\nprint(f\'Total Warehouse Valuation: ${total_valuation:,.2f}\')\nprint(f\'Total SKUs Requiring Reorder: {len(reorder_items)}\')\n', 'code_breakdown': [{'part': 'inventory.items()', 'role': 'Dict Iterator', 'explanation': 'Yields (key, value) pairs simultaneously for clean iteration over dictionary records.'}, {'part': "f'${total_valuation:,.2f}'", 'role': 'Comma Formatting', 'explanation': 'Adds comma separators for thousands (e.g. $10,450.00).'}], 'hints': ['Try updating the stock of SKU-101 to 10 and observe how the alert updates.']}}}, {'day': 5, 'title': 'Day 5: Modular Craftsmanship - Functions and Clean Code', 'description': 'Write reusable, modular, and maintainable software using functions, parameters, return values, type hints, and docstrings.', 'badge': 'Modular Craftsman', 'sessions': {'m1_concept': {'title': 'Morning 1: Functions - The Automated Kitchen Appliances', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': "The DRY Principle (Don't Repeat Yourself)", 'analogy': '☕ A function is like a high-end espresso machine: you give it inputs (beans, water), it runs its internal steps, and returns an espresso. You can use it 1,000 times without rewriting it.', 'content': 'Functions encapsulate reusable logic, isolate variable scope, and make large codebases maintainable.'}], 'quiz': [{'question': 'What is returned by a Python function that does not contain an explicit return statement?', 'options': ['None', '0', 'False', 'Empty string'], 'correct': 0, 'explanation': 'In Python, functions without an explicit return statement implicitly return None.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - AI Data Preprocessing Pipeline', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Build a Min-Max Feature Scaling normalization function commonly used to prepare numerical inputs for Neural Networks.', 'starter_code': '# ==========================================\n# AI MIN-MAX FEATURE NORMALIZER\n# ==========================================\n\ndef min_max_normalize(data_points: list[float]) -> list[float]:\n    """Normalizes an array of numbers to the range [0.0, 1.0]"""\n    if not data_points:\n        return []\n    \n    min_val = min(data_points)\n    max_val = max(data_points)\n    \n    if min_val == max_val:\n        return [0.0] * len(data_points)\n        \n    normalized = [(x - min_val) / (max_val - min_val) for x in data_points]\n    return [round(n, 3) for n in normalized]\n\nraw_speeds = [45.0, 80.0, 120.0, 30.0, 95.0, 60.0]\nscaled_speeds = min_max_normalize(raw_speeds)\n\nprint(\'Original Raw Speeds:\', raw_speeds)\nprint(\'Normalized AI Inputs [0.0 - 1.0]:\', scaled_speeds)\n', 'code_breakdown': [{'part': 'def min_max_normalize(data_points: list[float]) -> list[float]:', 'role': 'Function Signature & Type Hints', 'explanation': 'Clearly documents expected input type and return type for robust software engineering.'}, {'part': '"""Normalizes..."""', 'role': 'Docstring', 'explanation': 'Embedded documentation describing function behavior accessible via help().'}], 'goal': 'Verify normalized outputs strictly fall between 0.0 and 1.0.', 'hints': ['Min-Max scaling formula: (x - min) / (max - min).'], 'test_case': {'expected_output_contains': ['Normalized AI Inputs [0.0 - 1.0]: [0.167, 0.556, 1.0, 0.0, 0.722, 0.333]']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Functions and Scope', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Functions & Architecture', 'cards': [{'id': 'd5_c1', 'question': 'What do *args and **kwargs allow in Python functions?', 'answer': '`*args` captures variable positional arguments as a tuple.\n`**kwargs` captures variable keyword arguments as a dictionary.', 'code_snippet': "def log_event(event_name, *details, **meta):\n    print(f'Event: {event_name}')\n    print(f'Details: {details}')\n    print(f'Metadata: {meta}')"}, {'id': 'd5_c2', 'question': 'What is an anonymous lambda function in Python?', 'answer': 'A small single-expression function created with the `lambda` keyword.', 'code_snippet': 'square = lambda x: x ** 2\nprint(square(5))  # 25'}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated File Classifier & Organizer', 'duration_min': 30, 'type': 'mini_project', 'category': 'Automation & Scripting', 'instruction': 'Build an automated file categorizer function that scans a directory manifest and categorizes files into appropriate folders.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Automated File Classifier\n# ====================================================\n\nfile_manifest = [\n    'quarterly_report.pdf',\n    'dataset_train_v1.csv',\n    'resnet50_weights.pth',\n    'user_analytics.xlsx',\n    'profile_picture.png',\n    'meeting_notes.docx',\n    'system_backup.zip',\n    'api_config.json'\n]\n\nEXTENSION_RULES = {\n    'Documents': ['.pdf', '.docx', '.txt'],\n    'Datasets & Data': ['.csv', '.xlsx', '.json'],\n    'AI Models & Weights': ['.pth', '.onnx', '.h5'],\n    'Media': ['.png', '.jpg', '.mp4'],\n    'Archives': ['.zip', '.tar', '.gz']\n}\n\ndef classify_files(files: list[str]) -> dict[str, list[str]]:\n    results = {category: [] for category in EXTENSION_RULES}\n    results['Miscellaneous'] = []\n    \n    for filename in files:\n        matched = False\n        for category, extensions in EXTENSION_RULES.items():\n            if any(filename.endswith(ext) for ext in extensions):\n                results[category].append(filename)\n                matched = True\n                break\n        if not matched:\n            results['Miscellaneous'].append(filename)\n            \n    return results\n\norganized_files = classify_files(file_manifest)\n\nprint('=== 🗂️ AUTOMATED FOLDER ORGANIZER REPORT ===\\n')\nfor folder, files in organized_files.items():\n    if files:\n        print(f'📁 {folder}/ ({len(files)} files):')\n        for f in files:\n            print(f'   ├── {f}')\n", 'code_breakdown': [{'part': 'any(filename.endswith(ext) for ext in extensions)', 'role': 'Pattern Matcher', 'explanation': 'Checks if the current filename matches any allowed extensions in the category.'}, {'part': 'results = {category: [] ...}', 'role': 'Dict Comprehension', 'explanation': 'Initializes category buckets dynamically from the rule map.'}], 'hints': ['Notice how functions structure code so it can be re-run across different directories with a single call.']}}}, {'day': 6, 'title': 'Day 6: Advanced Sequences - Slicing, Tuples & Matrix Operations', 'description': 'Master multidimensional lists (matrices), tuple immutability, advanced slicing tricks (reverse, step), and memory efficiency.', 'badge': 'Matrix Master', 'sessions': {'m1_concept': {'title': 'Morning 1: Advanced Slicing & Tuples', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'The Power of Python Slicing `[start:stop:step]`', 'analogy': '✂️ Slicing is like a laser cutter for data: `data[1:5]` extracts a subset, `data[::2]` takes every second item, and `data[::-1]` reverses the entire sequence instantly.', 'content': 'Tuples are immutable sequences, meaning they cannot be modified after creation, making them thread-safe and usable as dictionary keys.'}], 'quiz': [{'question': 'What does numbers[::-1] do to a list?', 'options': ['Reverses the list', 'Extracts the last element', 'Sorts the list in ascending order', 'Clears the list'], 'correct': 0, 'explanation': 'A step of -1 traverses the sequence backwards from end to start.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - 2D Matrix Grid Transposition', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Transpose a 2D image kernel matrix (swap rows with columns) used in Computer Vision convolutional filters.', 'starter_code': "# ==========================================\n# 2D MATRIX TRANSPOSITION LAB (AI / CV)\n# ==========================================\n\nmatrix_grid = [\n    [1, 2, 3],\n    [4, 5, 6],\n    [7, 8, 9]\n]\n\ntransposed = [[row[i] for row in matrix_grid] for i in range(len(matrix_grid[0]))]\n\nprint('Original Matrix:')\nfor r in matrix_grid:\n    print(' ', r)\n\nprint('\\nTransposed Matrix (Swapped Rows/Cols):')\nfor r in transposed:\n    print(' ', r)\n", 'code_breakdown': [{'part': '[[row[i] for row in matrix_grid] for i in range(...)]', 'role': 'Nested List Comprehension', 'explanation': 'Iterates through column indices, collecting elements across each row into new columns.'}], 'goal': 'Verify transposed rows display [1, 4, 7], [2, 5, 8], [3, 6, 9].', 'hints': ['Python built-in zip(*matrix_grid) also transposes 2D lists!'], 'test_case': {'expected_output_contains': ['[1, 4, 7]', '[2, 5, 8]', '[3, 6, 9]']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Slicing & Immutability', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Advanced Sequences', 'cards': [{'id': 'd6_c1', 'question': 'Can a List be used as a Dictionary key? Why or why not?', 'answer': 'No. Lists are mutable and unhashable. Use a `tuple` instead as dictionary keys.', 'code_snippet': "coords = {(10, 20): 'Target Location'}"}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated Time-Series Resampler', 'duration_min': 30, 'type': 'mini_project', 'category': 'Data Science & AI/ML', 'instruction': 'Build a moving-average time-series smoother for stock price telemetry.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Stock Price Moving Average Smoother\n# ====================================================\n\nstock_prices = [142.5, 143.8, 145.2, 144.1, 147.0, 149.5, 148.2, 151.0, 153.4, 152.1]\nwindow_size = 3\n\ndef calculate_moving_average(prices, window):\n    moving_averages = []\n    for i in range(len(prices) - window + 1):\n        window_slice = prices[i : i + window]\n        avg = sum(window_slice) / window\n        moving_averages.append(round(avg, 2))\n    return moving_averages\n\nsmoothed_curve = calculate_moving_average(stock_prices, window_size)\nprint('Original Price Telemetry:', stock_prices)\nprint(f'3-Day Moving Average Trend: {smoothed_curve}')\n", 'code_breakdown': [{'part': 'prices[i : i + window]', 'role': 'Sliding Window Slice', 'explanation': 'Extracts consecutive subsets of window size 3 for moving averages.'}], 'hints': ['Moving averages filter out short-term market volatility noise.']}}}, {'day': 7, 'title': 'Day 7: Object-Oriented Architecture - Classes, Objects & self', 'description': 'Learn Object-Oriented Programming (OOP): Classes as blueprints, __init__ constructors, encapsulation, and instance methods.', 'badge': 'OOP Architect', 'sessions': {'m1_concept': {'title': 'Morning 1: Classes - The Architectural Blueprints', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Why OOP Matters for Production Systems', 'analogy': '🏭 A Class is like an architectural blueprint for an electric car. An Object is the actual car manufactured from that blueprint. The blueprint defines attributes (battery_capacity, model) and methods (charge(), drive()).', 'content': 'Classes bundle data attributes and behaviors together, preventing scattered global variables.'}], 'quiz': [{'question': 'What is the purpose of __init__ in a Python class?', 'options': ['It is the constructor method called automatically when creating a new object', 'It deletes objects from memory', 'It imports external modules', 'It makes methods private'], 'correct': 0, 'explanation': '`__init__` initializes object attributes when an instance is instantiated.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - AI Model Hyperparameter Container', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Create an AI Model Configuration class with methods to validate learning rates and display architectural configurations.', 'starter_code': "# ==========================================\n# AI MODEL CONFIGURATION OOP CLASS\n# ==========================================\n\nclass ModelConfig:\n    def __init__(self, model_name: str, learning_rate: float, batch_size: int):\n        self.model_name = model_name\n        self.learning_rate = learning_rate\n        self.batch_size = batch_size\n        \n    def validate_params(self) -> bool:\n        if self.learning_rate <= 0 or self.learning_rate > 1.0:\n            return False\n        if self.batch_size <= 0:\n            return False\n        return True\n        \n    def summary(self) -> str:\n        status = 'VALID' if self.validate_params() else 'INVALID'\n        return f'[{status}] Model: {self.model_name} | LR: {self.learning_rate} | Batch: {self.batch_size}'\n\ngpt_config = ModelConfig('Transformer-V3', 0.0003, 64)\nprint(gpt_config.summary())\n", 'code_breakdown': [{'part': 'def __init__(self, ...):', 'role': 'Constructor', 'explanation': "'self' refers to the specific instance being created, binding attributes to it."}, {'part': 'self.learning_rate = learning_rate', 'role': 'Instance Attribute', 'explanation': 'Stores learning rate inside this specific instance.'}], 'goal': 'Instantiate the config and verify the summary output.', 'hints': ['Try creating another instance with learning_rate = -5 and observe the INVALID status.'], 'test_case': {'expected_output_contains': ['[VALID] Model: Transformer-V3 | LR: 0.0003 | Batch: 64']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - OOP Principles', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Object-Oriented Programming', 'cards': [{'id': 'd7_c1', 'question': 'What is self in Python class methods?', 'answer': '`self` represents the explicit reference to the current instance of the class, allowing access to its attributes and methods.', 'code_snippet': "class Robot:\n    def __init__(self, name):\n        self.name = name\n    def greet(self):\n        print(f'Hello, I am {self.name}')"}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated Bank Account & Ledger Engine', 'duration_min': 30, 'type': 'mini_project', 'category': 'General Software Engineering', 'instruction': 'Build an enterprise BankAccount class supporting deposit, withdraw, transaction history logging, and overdraft protection.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Enterprise Bank Account & Ledger\n# ====================================================\n\nclass BankAccount:\n    def __init__(self, account_holder: str, initial_balance: float = 0.0):\n        self.holder = account_holder\n        self.balance = initial_balance\n        self.transactions = []\n        self.log_transaction('ACCOUNT_OPENED', initial_balance)\n        \n    def log_transaction(self, tx_type: str, amount: float):\n        self.transactions.append({'type': tx_type, 'amount': amount, 'balance_after': self.balance})\n        \n    def deposit(self, amount: float):\n        if amount <= 0:\n            raise ValueError('Deposit amount must be positive!')\n        self.balance += amount\n        self.log_transaction('DEPOSIT', amount)\n        print(f'💰 Deposited ${amount:.2f}. New Balance: ${self.balance:.2f}')\n        \n    def withdraw(self, amount: float):\n        if amount > self.balance:\n            print(f'🚫 WITHDRAWAL DENIED: Insufficient funds for ${amount:.2f} (Balance: ${self.balance:.2f})')\n            return False\n        self.balance -= amount\n        self.log_transaction('WITHDRAWAL', amount)\n        print(f'💸 Withdrew ${amount:.2f}. New Balance: ${self.balance:.2f}')\n        return True\n\naccount = BankAccount('Alex Hunter', 500.00)\naccount.deposit(250.00)\naccount.withdraw(100.00)\naccount.withdraw(1000.00)\nprint(f'\\nTotal Recorded Transactions: {len(account.transactions)}')\n", 'code_breakdown': [{'part': 'self.transactions.append(...)', 'role': 'Encapsulated State', 'explanation': 'Keeps audit trails inside the object instance without exposing internal structures globally.'}], 'hints': ['Notice how class methods enforce business rules and data safety.']}}}, {'day': 8, 'title': 'Day 8: File I/O & JSON Data Pipelines', 'description': 'Read and write CSV, JSON, and text files using context managers (with open), exception handling (try/except/finally), and JSON serialization.', 'badge': 'Pipeline Engineer', 'sessions': {'m1_concept': {'title': 'Morning 1: Safe File Handling & Context Managers', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'The Context Manager: with open(...)', 'analogy': '🚪 `with open(...)` is like an automatic revolving door: as soon as you step inside and finish your business, it guarantees the door closes behind you, preventing file locks or memory leaks even if an error crashes your code.', 'content': 'JSON is the universal data format of the modern web and AI APIs. Python provides dumps, loads, dump, and load.'}], 'quiz': [{'question': 'Why is with open(filename) as f: preferred over f = open(filename)?', 'options': ['It automatically closes the file even if exceptions occur', 'It makes file writing 100x faster', 'It encrypts file contents', 'It requires fewer imports'], 'correct': 0, 'explanation': 'Context managers guarantee resource cleanup upon exiting the block.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - JSON Config Serializer', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Parse an API telemetry JSON string, compute key metric statistics, and serialize updated report data.', 'starter_code': '# ==========================================\n# JSON API TELEMETRY PIPELINE\n# ==========================================\nimport json\n\nraw_api_payload = \'\'\'\n{\n    "service": "NeuralInferenceCluster",\n    "cluster_id": "US-EAST-4",\n    "latencies_ms": [12.4, 18.2, 9.8, 14.5, 31.0, 11.2],\n    "active_workers": 8\n}\n\'\'\'\n\ndata = json.loads(raw_api_payload)\nlatencies = data["latencies_ms"]\navg_latency = sum(latencies) / len(latencies)\nmax_latency = max(latencies)\n\ndata["metrics"] = {\n    "avg_latency_ms": round(avg_latency, 2),\n    "max_latency_ms": max_latency,\n    "sla_met": avg_latency < 20.0\n}\n\noutput_json = json.dumps(data, indent=2)\nprint(\'Processed & Augmented Telemetry:\')\nprint(output_json)\n', 'code_breakdown': [{'part': 'json.loads(...)', 'role': 'JSON Parser', 'explanation': 'Converts a raw JSON string into a native Python dictionary structure.'}, {'part': 'json.dumps(..., indent=2)', 'role': 'JSON Formatter', 'explanation': 'Converts a Python dictionary into a formatted, human-readable JSON string.'}], 'goal': 'Verify the output displays SLA met: true and average latency: 16.18ms.', 'hints': ['loads reads from a String, while load reads directly from a File stream.'], 'test_case': {'expected_output_contains': ['avg_latency_ms', 'sla_met']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Exceptions & I/O', 'duration_min': 30, 'type': 'flashcards', 'deck': 'File I/O & Exceptions', 'cards': [{'id': 'd8_c1', 'question': 'What is the order of execution in a try / except / else / finally block?', 'answer': '1. try: Code that might raise error\n2. except: Runs if error occurred\n3. else: Runs ONLY if NO error occurred\n4. finally: Runs ALWAYS regardless of outcome', 'code_snippet': "try:\n    x = 10 / 2\nexcept ZeroDivisionError:\n    print('Cannot divide by zero')\nelse:\n    print(f'Result: {x}')\nfinally:\n    print('Cleanup complete.')"}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Automated CSV Log Aggregator & Exporter', 'duration_min': 30, 'type': 'mini_project', 'category': 'Data Science & AI/ML', 'instruction': 'Build an automated log exporter that transforms telemetry records into clean CSV format.', 'starter_code': "# ====================================================\n# MINI-PROJECT: Automated CSV Telemetry Exporter\n# ====================================================\nimport csv\nimport io\n\nraw_records = [\n    {'timestamp': '2026-08-31 08:00', 'model': 'GPT-Vision', 'latency_ms': 42.1, 'tokens': 320},\n    {'timestamp': '2026-08-31 08:01', 'model': 'Claude-Fast', 'latency_ms': 18.5, 'tokens': 150},\n    {'timestamp': '2026-08-31 08:02', 'model': 'Llama-3-70B', 'latency_ms': 85.0, 'tokens': 540}\n]\n\noutput_stream = io.StringIO()\nfieldnames = ['timestamp', 'model', 'latency_ms', 'tokens']\n\nwriter = csv.DictWriter(output_stream, fieldnames=fieldnames)\nwriter.writeheader()\nwriter.writerows(raw_records)\n\ncsv_content = output_stream.getvalue()\nprint('=== 📊 GENERATED CSV EXPORT STREAM ===\\n')\nprint(csv_content)\n", 'code_breakdown': [{'part': 'csv.DictWriter(...)', 'role': 'CSV Formatter', 'explanation': 'Maps dictionary keys directly to CSV column headers.'}], 'hints': ["In production, replace StringIO with open('report.csv', 'w') to save directly to disk."]}}}, {'day': 9, 'title': 'Day 9: Pythonic Mastery - Decorators, Generators & Functional Tools', 'description': 'Elevate your coding to senior-level Python: Higher-order functions, custom @timer decorators, memory-efficient generators (yield), and itertools.', 'badge': 'Pythonic Guru', 'sessions': {'m1_concept': {'title': 'Morning 1: Decorators & Memory Generators', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'Decorators: Wrapping Functions with Superpowers', 'analogy': '🎁 A Decorator is like gift-wrapping a function: it takes your original function, wraps extra functionality around it (e.g., execution timers, auth checks, logging), and returns the enhanced version without modifying the original source code.', 'content': 'Generators (yield) compute values lazily on demand rather than storing millions of items in memory.'}], 'quiz': [{'question': 'What is the key advantage of a generator over a standard list?', 'options': ['Generators generate items on-demand, saving immense amounts of RAM', 'Generators execute 10x faster in all cases', 'Generators can only hold integers', 'Generators cannot be looped over'], 'correct': 0, 'explanation': 'Generators produce values one-at-a-time (lazy evaluation), maintaining constant O(1) memory footprint.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - Custom Performance Benchmark Decorator', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Create a reusable @benchmark decorator to measure function execution speed in milliseconds.', 'starter_code': '# ==========================================\n# PERFORMANCE BENCHMARK DECORATOR\n# ==========================================\nimport time\nimport functools\n\ndef benchmark(func):\n    @functools.wraps(func)\n    def wrapper(*args, **kwargs):\n        start_time = time.perf_counter()\n        result = func(*args, **kwargs)\n        elapsed_ms = (time.perf_counter() - start_time) * 1000\n        print(f\'⚡ [BENCHMARK] "{func.__name__}" executed in {elapsed_ms:.3f} ms\')\n        return result\n    return wrapper\n\n@benchmark\ndef train_simulated_network(iterations: int):\n    total = 0\n    for i in range(iterations):\n        total += (i ** 2) % 7\n    return total\n\noutput = train_simulated_network(100000)\nprint(\'Output Result:\', output)\n', 'code_breakdown': [{'part': '@functools.wraps(func)', 'role': 'Docstring Preserver', 'explanation': 'Preserves original function name and docstrings when wrapped.'}, {'part': '@benchmark', 'role': 'Decorator Syntax', 'explanation': 'Applies benchmark timing wrapper automatically to train_simulated_network.'}], 'goal': 'Verify the decorator prints execution time and returns the calculated output.', 'hints': ['Decorators are heavily used in frameworks like FastAPI, Flask, and PyTorch.'], 'test_case': {'expected_output_contains': ['[BENCHMARK]', 'train_simulated_network']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Generators & Closures', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Senior Python Patterns', 'cards': [{'id': 'd9_c1', 'question': 'What keyword turns a standard Python function into a Generator?', 'answer': 'The `yield` keyword.', 'code_snippet': 'def number_stream():\n    yield 1\n    yield 2\n    yield 3\n\nfor n in number_stream():\n    print(n)'}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Streaming Large Dataset Pipeline', 'duration_min': 30, 'type': 'mini_project', 'category': 'Data Science & AI/ML', 'instruction': 'Build a streaming generator that processes gigabyte-scale sensor batches in micro-chunks without memory spikes.', 'starter_code': '# ====================================================\n# MINI-PROJECT: Streaming Chunk Generator (AI Pipelines)\n# ====================================================\n\ndef stream_batch_generator(total_items: int, chunk_size: int):\n    """Generates data batches lazily with O(1) memory"""\n    for start in range(0, total_items, chunk_size):\n        chunk = list(range(start, min(start + chunk_size, total_items)))\n        yield chunk\n\nprint(\'🚀 Streaming 100,000 data points in chunks of 25,000...\')\nbatch_count = 0\nfor batch in stream_batch_generator(100000, 25000):\n    batch_count += 1\n    print(f\'Batch #{batch_count}: Size {len(batch)} items | Range [{batch[0]} ... {batch[-1]}]\')\n\nprint(\'\\n✅ All batches streamed with constant memory overhead.\')\n', 'code_breakdown': [{'part': 'yield chunk', 'role': 'Generator Yield', 'explanation': 'Pauses function state and hands the current chunk to caller, resuming on next iteration.'}], 'hints': ['Generators allow processing 100GB files on computers with only 4GB of RAM.']}}}, {'day': 10, 'title': 'Day 10: The Capstone - Autonomous AI Data Pipeline & Agent', 'description': "Integrate everything you've learned into a complete production-grade system: OOP, error logging, decorators, JSON pipelines, and automated analytics.", 'badge': 'Top Tier Python Engineer', 'sessions': {'m1_concept': {'title': 'Morning 1: Production Software Architecture', 'duration_min': 30, 'type': 'concept', 'sections': [{'heading': 'What Separates Top-Tier Engineers from Beginners', 'analogy': '🏗️ Beginners write monolithic scripts. Top engineers build modular, robust systems: defensive validation, clear separation of concerns, comprehensive logging, and testable components.', 'content': 'You now possess the core foundations to build high-performance data pipelines, automation bots, and AI models.'}], 'quiz': [{'question': 'What is the single most important rule in professional software architecture?', 'options': ['Separation of concerns (single responsibility per module)', 'Writing code with the fewest characters', 'Never using functions', 'Making all variables global'], 'correct': 0, 'explanation': 'Each class or function should focus on one well-defined responsibility.'}]}, 'm2_code': {'title': 'Morning 2: Code Lab - Full Pipeline Integration', 'duration_min': 30, 'type': 'coding_exercise', 'instruction': 'Run the complete analytics pipeline module and inspect final model scoring.', 'starter_code': '# ==========================================\n# CAPSTONE PIPELINE INTEGRATION\n# ==========================================\n\nclass DataPipeline:\n    def __init__(self, name: str):\n        self.name = name\n        self.pipeline_steps = []\n        \n    def add_step(self, step_name: str, func):\n        self.pipeline_steps.append((step_name, func))\n        \n    def execute(self, initial_data):\n        print(f\'🚀 Executing Pipeline: {self.name}\')\n        data = initial_data\n        for step_name, func in self.pipeline_steps:\n            data = func(data)\n            print(f\'  ✓ Step "{step_name}" complete. Data state count: {len(data)}\')\n        return data\n\nclean_step = lambda arr: [x for x in arr if x is not None and x > 0]\nscale_step = lambda arr: [round(x / max(arr), 3) for x in arr]\n\npipeline = DataPipeline(\'AI-Input-Normalizer\')\npipeline.add_step(\'Filter Clean\', clean_step)\npipeline.add_step(\'Scale Features\', scale_step)\n\nfinal_output = pipeline.execute([10, -5, None, 40, 80, None, 20])\nprint(\'Final Processed Vector:\', final_output)\n', 'code_breakdown': [{'part': 'pipeline.add_step(...)', 'role': 'Pipeline Pattern', 'explanation': 'Allows dynamically chaining transformation stages into clean reusable workflows.'}], 'goal': 'Verify output produces clean vector: [0.125, 0.5, 1.0, 0.25].', 'hints': ['Observe how composable pipelines scale to massive datasets.'], 'test_case': {'expected_output_contains': ['[0.125, 0.5, 1.0, 0.25]']}}, 'e1_flashcards': {'title': 'Evening 1: Active Recall - Senior Architecture', 'duration_min': 30, 'type': 'flashcards', 'deck': 'Software Architecture', 'cards': [{'id': 'd10_c1', 'question': 'What is the SOLID principle in Software Engineering?', 'answer': '1. Single Responsibility\n2. Open/Closed\n3. Liskov Substitution\n4. Interface Segregation\n5. Dependency Inversion', 'code_snippet': '# Clean modular design is key to scalable Python systems'}]}, 'e2_project': {'title': 'Evening 2: Mini-Project - Autonomous AI Agent Engine', 'duration_min': 30, 'type': 'mini_project', 'category': 'Data Science & AI/ML', 'instruction': 'Build an autonomous AI agent task manager that parses user queries, decides tool routing, and executes automated data actions.', 'starter_code': '# ====================================================\n# CAPSTONE: Autonomous AI Agent Tool Dispatcher\n# ====================================================\n\nclass AIAgent:\n    def __init__(self, agent_name: str):\n        self.name = agent_name\n        self.tool_registry = {}\n        \n    def register_tool(self, tool_name: str, tool_fn):\n        self.tool_registry[tool_name] = tool_fn\n        \n    def run_query(self, user_intent: str, data_payload):\n        print(f\'🤖 Agent "{self.name}" received query: "{user_intent}"\')\n        if "summarize" in user_intent.lower():\n            return self.tool_registry["summarize"](data_payload)\n        elif "anomaly" in user_intent.lower():\n            return self.tool_registry["anomaly"](data_payload)\n        else:\n            return "❓ Unknown intent: No suitable tool registered."\n\ndef summarize_tool(data):\n    return f\'Dataset contains {len(data)} items | Sum: {sum(data)} | Mean: {sum(data)/len(data):.2f}\'\n\ndef anomaly_tool(data):\n    mean_val = sum(data)/len(data)\n    anomalies = [x for x in data if abs(x - mean_val) > (mean_val * 0.8)]\n    return f\'Detected {len(anomalies)} anomalies: {anomalies}\'\n\nagent = AIAgent(\'PyMaster-AI\')\nagent.register_tool(\'summarize\', summarize_tool)\nagent.register_tool(\'anomaly\', anomaly_tool)\n\nsensor_feed = [22.4, 21.8, 23.1, 98.5, 22.0, 21.9, 105.2]\nprint(agent.run_query(\'Summarize current sensor readings\', sensor_feed))\nprint(agent.run_query(\'Find any anomaly in the telemetry\', sensor_feed))\n', 'code_breakdown': [{'part': 'self.tool_registry[tool_name] = tool_fn', 'role': 'Tool Dispatcher Pattern', 'explanation': 'The core architectural design pattern powering modern LLM Agent frameworks like LangChain, AutoGen, and CrewAI.'}], 'hints': ['Congratulations on completing the entire core mastery path!']}}}]

def get_curriculum():
    return CURRICULUM

def get_day_lesson(day_num: int):
    for d in CURRICULUM:
        if d["day"] == day_num:
            return d
    return None

def get_all_flashcards():
    cards = []
    for day in CURRICULUM:
        e1 = day.get("sessions", {}).get("e1_flashcards", {})
        for card in e1.get("cards", []):
            c = dict(card)
            c["deck"] = e1.get("deck", "General")
            cards.append(c)
    return cards
